// Name: Extract Title + Slug + MDX (robust)
// Input: items[0].json.input_schema (string)
// Output: title, slug, fileContent

const item = items[0].json;
const mdx = String(item.input_schema || '');

function findTitleFromFrontmatter(text) {
  // Grab the first frontmatter block (single or multi-line)
  const fm = text.match(/---\s*([\s\S]*?)\s*---/);
  if (!fm) return null;
  const body = fm[1];

  // Look for title: "..."
  // Works whether title is on same line as '---' or later lines.
  const mQuoted = body.match(/(?:^|\s)title:\s*"(.*?)"/i) || body.match(/(?:^|\s)title:\s*'(.*?)'/i);
  if (mQuoted && mQuoted[1]) return mQuoted[1].trim();

  // Unquoted (less common)
  const mBare = body.match(/(?:^|\s)title:\s*([^\n\r]+)\s*$/im);
  if (mBare && mBare[1]) return mBare[1].trim();

  return null;
}

function findTitleFromH1(text) {
  const h1 = text.match(/^#\s+(.+?)\s*$/m);
  return h1 ? h1[1].trim() : null;
}

function slugify(s) {
  return s
    .normalize('NFKD')                   // fold accents
    .replace(/[\u0300-\u036f]/g, '')     // remove diacritics
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')         // non-alnum → dash
    .replace(/^-+|-+$/g, '');            // trim dashes
}

let title = findTitleFromFrontmatter(mdx) || findTitleFromH1(mdx) || 'untitled';
const slug = slugify(title) || 'untitled';

return [{
  json: {
    ...item,
    title,
    slug,
    fileContent: mdx
  }
}];

// Guard + Format: Extract MDX and format it properly (using $json like old version)
const item = $json;
let mdx = String(
  item.input_schema
  ?? item.query?.body_mdx
  ?? item.query?.mdx
  ?? item.query
  ?? item.query?.html
  ?? item.mdx
  ?? item.html
  ?? item.content
  ?? ''
).trim();

if (!mdx) {
  // Debug: show what fields are available
  const availableFields = Object.keys(item).join(', ');
  throw new Error(`POSTBLOG: input_schema is EMPTY. Available fields: ${availableFields}`);
}

// FORMAT: Fix squished frontmatter and content
const parts = mdx.match(/^(---[\s\S]*?---)\s*([\s\S]*)$/);
if (parts) {
  let frontmatter = parts[1];
  let body = parts[2];

  // Fix frontmatter if squished (all on one line)
  if (frontmatter.includes('title:') && !frontmatter.includes('\ntitle:')) {
    frontmatter = frontmatter
      .replace(/title:\s*"([^"]+)"/i, 'title: "$1"')
      .replace(/date:\s*"([^"]+)"/i, '\ndate: "$1"')
      .replace(/excerpt:\s*"([^"]+)"/i, '\nexcerpt: "$1"')
      .replace(/tags:\s*(\[[^\]]+\])/i, '\ntags: $1')
      .replace(/coverImage:\s*"([^"]+)"/i, '\ncoverImage: "$1"');
    if (!frontmatter.startsWith('---')) frontmatter = '---' + frontmatter;
    if (!frontmatter.endsWith('---')) frontmatter = frontmatter + '\n---';
  }

  // Fix body formatting
  body = body.replace(/  /g, '\n');  // Double space → newline
  body = body.replace(/([^\n])(#{1,6}\s)/g, '\n\n$2');  // Headings
  body = body.replace(/([^\n])(---)([^\n])/g, '\n\n---\n\n');  // Horizontal rules
  body = body.replace(/([^\n])(>\s)/g, '\n\n$2');  // Blockquotes
  body = body.replace(/([^\n])(!\[|<img)/g, '\n\n$2');  // Images
  body = body.replace(/\n{3,}/g, '\n\n');  // Max 2 newlines

  mdx = frontmatter + '\n\n' + body.trim();
}

return [{ json: { ...item, input_schema: mdx } }];
